  <div id="stage">
    <canvas id="board" width="600" height="600"></canvas>

    <!-- START MENU -->
    <div class="overlay" id="menu">
      <h2 class="win">Snake</h2>
      <p>30 × 30 grid &middot; 4-direction movement<br>Hit a wall or yourself and the round ends.</p>
      <div class="modes">
